'use strict';
// Progressive enhancement; original map, fossils and place search remain independent.
const homeStartWithProject=!location.hash;
const home={open:false,prefs:HomeEngine.defaults(),region:'',size:'',radius:0,strict:false,sort:'best',rows:[],results:[],page:0,seq:0,ready:false,layer:false,reference:null};
const homeCities=new Map();let homeMeta,homeRecent;
function homeSave(){try{localStorage.setItem('chronoterre-home-v1',JSON.stringify({prefs:home.prefs,region:home.region,size:home.size,radius:home.radius,reference:home.reference}));}catch{}}
function homeRestore(){try{const p=JSON.parse(localStorage.getItem('chronoterre-home-v1')||'null');if(p&&HomeEngine.valid(p.prefs)){home.prefs=p.prefs;home.region=String(p.region||'');home.size=['','small','medium','large'].includes(p.size)?p.size:'';home.radius=[0,50,100,200,500].includes(p.radius)?p.radius:0;home.reference=homeCities.has(p.reference)?p.reference:null;}}catch{}}
const regions={'11':'Île-de-France','24':'Centre-Val de Loire','27':'Bourgogne-Franche-Comté','28':'Normandie','32':'Hauts-de-France','44':'Grand Est','52':'Pays de la Loire','53':'Bretagne','75':'Nouvelle-Aquitaine','76':'Occitanie','84':'Auvergne-Rhône-Alpes','93':'Provence-Alpes-Côte d’Azur','94':'Corse'};
function homeOpen(){home.open=true;$('#home-panel').hidden=false;$('#place-panel').hidden=true;$('#past-filters').hidden=true;if(state.mode!=='living')setMode('living');$('#home-panel').hidden=false;$('#place-panel').hidden=true;homeForm();onMobile();}
function homeClose(){home.open=false;$('#home-panel').hidden=true;$('#place-panel').hidden=false;home.layer=false;homeMap();}
function homeForm(){
 const ref=homeCities.get(home.reference);
 $('#home-panel').innerHTML=`<section class="home-intro"><div class="eyebrow">TON PROCHAIN CHAPITRE</div><h1>Où te sentirais-tu<br><em>le mieux ?</em></h1><p>Explore les communes qui correspondent à tes préférences climatiques. Puis vérifie les risques et le logement.</p><div class="home-pills"><span>France & Corse</span><span>Sans compte supplémentaire</span></div><button class="primary wide home-quick" type="submit" form="home-form">Voir les résultats · ajuster ci-dessous ↓</button></section>
 <form id="home-form"><section class="home-step"><h2><b>1</b> Ton projet</h2><label>Horizon<select id="home-horizon"><option value="ref">Référence historique · 1976–2005</option><option value="2030">2030 · TRACC</option><option value="2050">2050 · TRACC</option><option value="2100">2100 · TRACC</option><option disabled>+50 ans : période indisponible</option></select></label><div class="home-fields"><label>Région<select id="home-region"><option value="">Toute la métropole</option>${Object.entries(regions).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>Population communale<select id="home-size"><option value="">Indifférent</option><option value="small">Moins de 5 000</option><option value="medium">5 000 à 50 000</option><option value="large">Plus de 50 000</option></select></label></div><label>Autour de mon point de repère<select id="home-radius"><option value="0">Sans limite de distance</option>${[50,100,200,500].map(r=>`<option value="${r}">${r} km à vol d’oiseau</option>`).join('')}</select></label><div class="home-reference">${ref?`Repère : <b>${esc(ref.name)}</b>`:'Aucun repère choisi.'} <button type="button" id="home-use-current" class="textlink">Utiliser ${esc(state.place?.commune_name||state.place?.name||'la commune sélectionnée')}</button></div></section>
 <section class="home-step"><h2><b>2</b> Ce qui compte pour toi</h2><p class="section-note">Tes maxima souhaités, pas des seuils officiels de danger. « Ignorer » retire un critère.</p>${HomeEngine.metrics.map((m,i)=>`<div class="home-criterion"><label for="home-limit-${i}">${esc(m.label)}<small>${esc(m.detail)}</small></label><div class="home-fields"><label class="home-number">Maximum (${esc(m.unit)})<input id="home-limit-${i}" type="number" min="0" max="${m.max}" step="1" value="${home.prefs[i].limit}" required></label><label>Importance<select id="home-weight-${i}"><option value="0">Ignorer</option><option value="1">Utile</option><option value="2">Important</option><option value="3">Prioritaire</option></select></label></div></div>`).join('')}<button type="button" id="home-reset" class="textlink">Réinitialiser mes préférences</button></section>
 <section class="home-step home-submit"><label class="home-check"><input type="checkbox" id="home-strict" ${home.strict?'checked':''}> Garder seulement les communes respectant tous mes seuils</label><p class="home-limit">Risques à l’adresse, emploi, prix, services et confort du bâtiment : non évalués dans ce classement.</p><button class="primary wide" type="submit">Explorer les résultats →</button><p id="home-error" role="alert"></p></section></form><div id="home-results" aria-live="polite"></div>`;
 $('#home-horizon').value=state.horizon;$('#home-region').value=home.region;$('#home-size').value=home.size;$('#home-radius').value=String(home.radius);home.prefs.forEach((p,i)=>$('#home-weight-'+i).value=String(p.weight));
 $('#home-use-current').onclick=()=>{home.reference=state.place?.code||null;home.ready=false;homeSave();homeForm();};$('#home-reset').onclick=()=>{home.prefs=HomeEngine.defaults();home.strict=false;home.ready=false;homeSave();homeForm();};
 $('#home-form').onsubmit=e=>{e.preventDefault();const p=HomeEngine.metrics.map((m,i)=>({limit:Number($('#home-limit-'+i).value),weight:Number($('#home-weight-'+i).value)}));if(!HomeEngine.valid(p)){$('#home-error').textContent='Active au moins un critère et vérifie les seuils.';return;}home.prefs=p;home.region=$('#home-region').value;home.size=$('#home-size').value;home.radius=Number($('#home-radius').value);home.strict=$('#home-strict').checked;if(home.radius&&!home.reference){$('#home-error').textContent='Choisis un point de repère avec le bouton ci-dessus.';return;}homeSave();const h=$('#home-horizon').value;if(h!==state.horizon)document.querySelector(`[data-h="${h}"]`).click();else homeRun();};
}
async function homeRun(){
 if(!home.open)return;const token=++home.seq;home.ready=false;home.page=0;home.layer=false;homeMap();$('#home-results').innerHTML='<div class="loading">Calcul sur les communes documentées…</div>';
 try{const [rows,metadata]=await Promise.all([data(`home-${state.horizon}.json`),data('home-meta.json')]);if(token!==home.seq||!home.open)return;homeMeta=metadata;home.rows=rows;home.results=[];const ref=homeCities.get(home.reference);
 for(const row of rows){const c=homeCities.get(row[0]);if(!c)continue;if(home.region&&c.region!==home.region)continue;if(home.size&&(c.population===null||(home.size==='small'&&c.population>=5000)||(home.size==='medium'&&(c.population<5000||c.population>50000))||(home.size==='large'&&c.population<=50000)))continue;if(home.radius&&ref&&km(c.longitude,c.latitude,ref.longitude,ref.latitude)>home.radius)continue;const fit=HomeEngine.evaluate(row,home.prefs);home.results.push({city:c,row,fit});}
 home.ready=true;home.layer=true;homeRenderResults();homeMap();if(mapReady&&home.visible.length){const coords=home.visible.map(r=>[r.city.longitude,r.city.latitude]).filter(c=>c.every(Number.isFinite));if(coords.length){const b=coords.reduce((b,c)=>[Math.min(b[0],c[0]),Math.min(b[1],c[1]),Math.max(b[2],c[0]),Math.max(b[3],c[1])],[180,90,-180,-90]);map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:55,maxZoom:10});}}$('#home-results').scrollIntoView?.({behavior:'smooth',block:'start'});
 }catch(e){if(token===home.seq)$('#home-results').innerHTML=`<div class="home-step"><h2>Résultats indisponibles</h2><p>${esc(e.message)}</p><button id="home-retry" class="outline">Réessayer</button></div>`;$('#home-retry')?.addEventListener('click',homeRun);}
}
function homeRenderResults(){
 const totals=[0,0,0,0];home.results.forEach(r=>totals[r.fit.category]++);const visible=home.results.filter(r=>!home.strict||r.fit.category===0).sort((a,b)=>HomeEngine.compare(a,b,home.sort==='least'));home.visible=visible;const page=visible.slice(home.page*12,home.page*12+12);
 $('#home-results').innerHTML=`<section class="home-step"><div class="eyebrow">TES RÉSULTATS · ${state.horizon==='ref'?'1976–2005':esc(state.horizon)+' / TRACC'}</div><h2>${fmt(totals[0],0)} communes dans tes seuils</h2><p class="section-note">Sur ${fmt(home.results.length,0)} communes dans ton périmètre. Référence et projections de même source. Risques et urbanisme à vérifier séparément.</p><div class="home-distribution">${totals.map((v,i)=>`<span style="flex:${v||.01};background:${['#147d76','#d6a75e','#985578','#8b959b'][i]}" title="${esc(HomeEngine.labels[i])} : ${v}"></span>`).join('')}</div><div class="home-counts">${totals.map((v,i)=>`<span><i class="home-dot cat-${i}"></i>${fmt(v,0)} · ${esc(HomeEngine.labels[i])}</span>`).join('')}</div><div class="home-result-actions"><button id="home-method" class="textlink">Comment est-ce calculé ?</button><button id="home-export" class="textlink">↓ Exporter les résultats</button></div><label>Ordre des résultats<select id="home-sort"><option value="best">Les plus proches de mes critères</option><option value="least">Les plus éloignés de mes critères</option></select></label><p class="section-note">${home.strict?'Filtre strict actif : seuls les lieux dans tous tes seuils sont listés.':'Les données insuffisantes restent en fin de liste dans les deux sens.'} Les ex æquo sont présentés par ordre alphabétique.</p>${page.length?page.map(r=>homeCard(r)).join(''):'<div class="empty">Aucune commune ne correspond à ces contraintes. Modifie le périmètre ou tes seuils.</div>'}<div class="home-pagination"><button id="home-prev" class="outline" ${home.page===0?'disabled':''}>←</button><span>${visible.length?home.page*12+1:0}–${Math.min((home.page+1)*12,visible.length)} / ${fmt(visible.length,0)}</span><button id="home-next" class="outline" ${(home.page+1)*12>=visible.length?'disabled':''}>Suivant →</button></div></section>`;
 $('#home-sort').value=home.sort;$('#home-sort').onchange=e=>{home.sort=e.target.value;home.page=0;homeRenderResults();};$('#home-prev').onclick=()=>{home.page--;homeRenderResults();};$('#home-next').onclick=()=>{home.page++;homeRenderResults();};$('#home-method').onclick=homeMethod;$('#home-export').onclick=homeExport;
 $$('[data-home-open]').forEach(b=>b.onclick=()=>homeSelect(b.dataset.homeOpen));$$('[data-home-why]').forEach(b=>b.onclick=()=>homeWhy(b.dataset.homeWhy));
}
function homeCard(r){const {city:c,fit:f}=r;const sens=HomeEngine.sensitivity(r.row,home.prefs,state.horizon);return `<article class="home-card"><div class="home-card-top"><span class="home-category cat-text-${f.category}">${esc(f.label)}</span><span>${f.missing?'Incomplet':f.matched+'/'+f.total+' critères'}</span></div><h3>${esc(c.name)} <small>${esc(c.department)}</small></h3><p>${fmt(c.population,0)} habitants · ${esc(sens.label)}</p><div class="home-chips">${f.details.slice(0,3).map(d=>{const m=HomeEngine.metrics.find(x=>x.id===d.id);return `<span>${esc(m.label)} <b>${fmt(d.value)} ${esc(m.unit)}</b></span>`;}).join('')}</div><p class="home-card-warning">Risques du terrain et logement : à vérifier</p><div class="home-card-actions"><button class="primary" data-home-open="${esc(c.code)}">Voir le lieu</button><button class="outline" data-home-why="${esc(c.code)}">Pourquoi ?</button></div></article>`;}
function homeMethod(){modal('Des préférences explicites, pas une promesse',`<p>Ce parcours compare uniquement cinq indicateurs climatiques de Météo-France, en métropole et en Corse, à horizon et source constants. La résolution source est d’environ 8 km.</p><h3>Catégories</h3><p>Tous les critères actifs respectent tes maxima : « Dans tous tes seuils ». Au moins la moitié : « Des compromis ». Moins de la moitié : « Plus éloigné ». Une valeur centrale manquante suffit à rendre le résultat insuffisant.</p><h3>Ordre des résultats</h3><p>Les catégories sont prioritaires. Dans chaque catégorie, nous additionnons, pour chaque critère actif : importance × max(0, valeur − seuil) / max(1, seuil). Plus cette somme est petite, plus les dépassements sont limités. Un ex æquo est départagé par nom puis code INSEE ; ce n’est pas une supériorité climatique. Les poids ne changent pas les catégories.</p><h3>Sensibilité</h3><p>La catégorie est recalculée aux bornes basses puis hautes publiées pour chacun des indicateurs. Ce test mesure une sensibilité aux bornes marginales, pas un scénario climatique conjoint, un intervalle de confiance du classement ou une probabilité. Aucun scénario d’émissions n’est comparé à la TRACC.</p><h3>Ce qui ne rentre pas dans ce calcul</h3><p>Inondations, incendies, disponibilité de l’eau, urbanisme, logement, prix, services, soleil et vent ne sont pas évalués ici. La séquence sèche ne mesure pas la disponibilité d’eau potable. Un bon résultat climatique ne valide pas un achat. Aucune projection 2076 n’est interpolée.</p><p>Historique Climadiag : 1976–2005. Réanalyse récente ERA5-Land : vue séparée sur dix lieux, sans soustraction avec DRIAS. Les fenêtres annuelles propres aux modèles TRACC ne sont pas fournies dans l’export utilisé.</p>${link('https://climadiag-commune.meteofrance.com/','Définitions et projections Météo-France')}<p>Actualisation : ${esc(homeMeta?.source?.fetched_at?.slice(0,10)||'voir provenance')} · Licence Ouverte Etalab. Mise à jour manuelle.</p>`);}
function homeWhy(code){const r=home.results.find(x=>x.city.code===code);if(!r)return;const s=HomeEngine.sensitivity(r.row,home.prefs,state.horizon);modal('Pourquoi '+r.city.name+' ?',`<p><b>${esc(r.fit.label)}</b> · ${esc(state.horizon==='ref'?'Référence 1976–2005':'TRACC '+state.horizon)}</p><div class="table-wrap"><table><thead><tr><th>Critère</th><th>Valeur centrale</th><th>Ton maximum</th><th>Résultat</th></tr></thead><tbody>${r.fit.details.map(d=>{const m=HomeEngine.metrics.find(m=>m.id===d.id);return `<tr><th>${esc(m.label)}</th><td>${fmt(d.value)} ${esc(m.unit)}</td><td>${d.limit??'—'}</td><td>${d.pass===null?'Manquant':d.pass?'Dans le seuil':'Dépassement'}</td></tr>`;}).join('')}</tbody></table></div><p>${esc(s.label)}. Les bornes ne sont pas des probabilités.</p><div class="callout">Ce résultat concerne le climat représentatif de la commune. Il reste à vérifier les risques à l’adresse, les documents d’urbanisme et le confort réel du bâtiment.</div><button id="home-why-method" class="outline">Voir toute la méthode</button>`);$('#home-why-method').onclick=homeMethod;}
async function homeSelect(code){home.open=false;$('#home-panel').hidden=true;$('#place-panel').hidden=false;await selectCity(code);onMobile();}
function homeMap(){if(!mapReady)return;const empty={type:'FeatureCollection',features:[]};if(!map.getSource('home-fit')){map.addSource('home-fit',{type:'geojson',data:empty,cluster:true,clusterRadius:24,clusterMaxZoom:7});map.addLayer({id:'home-clusters',type:'circle',source:'home-fit',filter:['has','point_count'],paint:{'circle-color':'#35596a','circle-radius':['step',['get','point_count'],9,50,14,500,19],'circle-opacity':.72,'circle-stroke-color':'#fff','circle-stroke-width':1}});map.addLayer({id:'home-points',type:'circle',source:'home-fit',filter:['!', ['has','point_count']],paint:{'circle-radius':6,'circle-color':['match',['get','category'],0,'#147d76',1,'#d6a75e',2,'#985578','#8b959b'],'circle-stroke-color':'#fff','circle-stroke-width':1}});map.on('click','home-points',e=>{e.preventDefault();homeSelect(e.features[0].properties.code);});map.on('click','home-clusters',async e=>{e.preventDefault();const f=e.features[0],z=await map.getSource('home-fit').getClusterExpansionZoom(f.properties.cluster_id);map.easeTo({center:f.geometry.coordinates,zoom:z});});}
 const active=home.layer&&state.mode==='living';if(!active&&state.mode==='living')$('#legend').innerHTML='<b>Informations cartographiées</b><span><i class="blue"></i>Enveloppes de crue · Toulouse</span><span><i class="ochre"></i>Argiles · secteur Bordeaux</span><small>Zonages actuels, indépendants de l’horizon climatique</small>';map.getSource('home-fit').setData(active?{type:'FeatureCollection',features:home.results.filter(r=>!home.strict||r.fit.category===0).filter(r=>Number.isFinite(r.city.longitude)&&Number.isFinite(r.city.latitude)).map(r=>({type:'Feature',geometry:{type:'Point',coordinates:[r.city.longitude,r.city.latitude]},properties:{code:r.city.code,category:r.fit.category}}))}:empty);
 if(active)$('#legend').innerHTML='<b>Adéquation climatique · '+esc(state.horizon==='ref'?'1976–2005':state.horizon)+'</b><span><i style="background:#147d76"></i>Dans tes seuils</span><span><i style="background:#d6a75e"></i>Compromis</span><span><i style="background:#985578"></i>Plus éloigné</span><span><i style="background:#8b959b"></i>Données insuffisantes</span><small>Groupes bleu foncé : zoomez · points communaux, pas des zones de sécurité. Aléas actuels toujours distincts.</small>';
}
function homeExport(){download('ChronoTerre_mon_projet_'+state.horizon+'.json',{generated_at:new Date().toISOString(),horizon:state.horizon,scenario:state.horizon==='ref'?'reference':'TRACC',preferences:home.prefs.map((p,i)=>({...HomeEngine.metrics[i],...p})),filters:{region:home.region,population:home.size,radius_km:home.radius,reference_code:home.reference,strict:home.strict},order:home.sort,provenance:homeMeta,results:home.visible.map(r=>({commune:r.city.code,name:r.city.name,values:r.row.slice(1),assessment:r.fit,sensitivity:HomeEngine.sensitivity(r.row,home.prefs,state.horizon)})),limits:'Adéquation climatique uniquement. Risques, réglementation, logement et qualité de vie non évalués. Les bornes ne constituent pas des probabilités.'});}
function homeRowFromClimate(climate,h){return [climate.place.commune_code,...HomeEngine.metrics.map(m=>{const r=val(climate,m.id,h,['G4','AG1'].includes(m.id)?'été':'annuel');return r?r.slice(3):[null,null,null];})];}
function homeOnPlace(){
 if(!state.place||state.mode!=='living'||!$('#place-panel .place-head'))return;$('#place-panel .home-place-fit')?.remove();const supported=state.climate?.place.domain==='France hexagonale';const row=supported?homeRowFromClimate(state.climate,state.horizon):null;const fit=row?HomeEngine.evaluate(row,home.prefs):null;
 $('#place-panel .place-head').insertAdjacentHTML('afterend',`<section class="content-section home-place-fit"><div class="eyebrow">TON PROJET D’INSTALLATION</div><h2>${fit?esc(fit.label):'Adéquation non calculée'}</h2><p>${fit?`${fit.matched} / ${fit.total} critères climatiques dans tes seuils.`:'Classement limité à la métropole et à la Corse.'} Les risques à l’adresse restent à examiner.</p><button id="home-return" class="outline wide">← Mes préférences et résultats</button><div class="home-place-buttons"><button id="home-timeline" class="textlink">Climat à travers le temps →</button><button id="home-building" class="textlink">Vérifier le logement →</button><button id="home-compare-reference" class="textlink">Comparer avec mon repère →</button></div></section>`);
 $('#home-return').onclick=()=>{home.open=true;$('#home-panel').hidden=false;$('#place-panel').hidden=true;if(!$('#home-form'))homeForm();if(home.ready)homeRenderResults();else homeRun();home.layer=home.ready;homeMap();};$('#home-timeline').onclick=homeTimeline;$('#home-building').onclick=homeBuilding;$('#home-compare-reference').onclick=homeCompareReference;
}
async function homeCompareReference(){const c=homeCities.get(home.reference);if(!c)return modal('Choisir mon point de repère','<p>Recherchez votre commune actuelle, puis ouvrez « Trouver mon lieu » et choisissez « Utiliser cette commune ». Seul le code communal est conservé sur cet appareil.</p>');try{if(!state.comparison.some(x=>x.code===state.place.code))addCompare();if(!state.comparison.some(x=>x.code===c.code)){if(state.comparison.length>=4)return notify('Retirez un lieu du comparateur pour ajouter votre repère.');state.comparison.push({...c,climate:await climateFor(c)});$('#compare-count').textContent=state.comparison.length;}showComparison();}catch(e){notify('Comparaison indisponible : '+e.message);}}
async function homeTimeline(metricId='S1'){
 const selectedCode=state.place.code,climate=state.climate,m=HomeEngine.metrics.find(x=>x.id===metricId)||HomeEngine.metrics[0],season=['G4','AG1'].includes(m.id)?'été':'annuel';const periods=['ref','2030','2050','2100'],values=periods.map(h=>val(climate,m.id,h,season)),max=Math.max(1,...values.map(v=>v?.[5]??v?.[3]??0));
 modal('Le climat de '+state.place.name,`<div class="home-timeline-intro"><span class="badge neutral">Même source · Météo-France</span><p>La référence historique et les projections restent distinctes de la réanalyse récente présentée plus bas.</p></div><label>Indicateur<select id="home-trend-metric">${HomeEngine.metrics.map(m=>`<option value="${m.id}">${esc(m.label)}</option>`).join('')}</select></label><div class="home-chart" role="img" aria-label="Valeurs climatiques aux horizons de référence, 2030, 2050 et 2100">${values.map((v,i)=>`<div class="home-chart-column"><b>${fmt(v?.[3])}</b><div class="home-chart-track"><div style="height:${Math.max(1,(v?.[3]||0)/max*100)}%;background:${i===0?'#8b9da5':'#167d76'}"></div></div><strong>${periods[i]==='ref'?'Référence':periods[i]}</strong><small>${esc(m.unit)}</small></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Période</th><th>Valeur centrale</th><th>Borne basse</th><th>Borne haute</th></tr></thead><tbody>${values.map((v,i)=>`<tr><th>${periods[i]==='ref'?esc(climate?.place.reference_start+'–'+climate?.place.reference_end):'TRACC '+periods[i]}</th><td>${fmt(v?.[3])}</td><td>${fmt(v?.[4])}</td><td>${fmt(v?.[5])}</td></tr>`).join('')}</tbody></table></div><p class="section-note">${esc(climate?.place.resolution||'Échelle non fournie')}. Les barres montrent les valeurs centrales ; bornes publiées dans le tableau. Pas de valeur annuelle exacte ni d’interpolation à 2076.</p><section id="home-recent"><h3>Les années récentes · 2016–2025</h3><p>Lecture des séries disponibles…</p></section><p>${link('https://climadiag-commune.meteofrance.com/','Source des projections et définitions')}</p>`);
 $('#home-trend-metric').value=m.id;$('#home-trend-metric').onchange=e=>homeTimeline(e.target.value);
 try{homeRecent=homeRecent||await data('recent.json');if(!$('#home-recent')||state.place.code!==selectedCode)return;const p=homeRecent.places[selectedCode];$('#home-recent').innerHTML=`<h3>Les années récentes · 2016–2025</h3><p><b>ERA5-Land · réanalyse</b>, observations et modèle. Ce ne sont pas des relevés de station. Maille 0,1° (environ 11 km), altitude de maille, sans correction locale.</p>${p?`<div class="table-wrap"><table><thead><tr><th>Année complète</th><th>Max. ≥35 °C (j)</th><th>Min. ≥20 °C (j)</th><th>Gel (j)</th></tr></thead><tbody>${p.annual.map(y=>`<tr><th>${y.year}</th><td>${y.hot_days}</td><td>${y.warm_min_days}</td><td>${y.frost_days}</td></tr>`).join('')}</tbody></table></div><p class="section-note">${p.annual.reduce((n,y)=>n+y.days,0)} journées validées. Minimum quotidien ≥20 °C : indicateur de chaleur persistante, pas un décompte horaire des nuits. Maille retournée : ${p.grid.latitude}, ${p.grid.longitude}. Récupéré le ${esc(p.provenance.retrieved_at.slice(0,10))}.</p>`:`<div class="empty">Aucune série récente validée pour cette commune. ${Object.keys(homeRecent.places).length} lieux sont couverts ; cette absence n’améliore pas son classement.</div>`}<p class="section-note">Aucune extrapolation de ces dix années. Aucun écart calculé entre ERA5-Land et DRIAS. Les précipitations manquent dans les réponses reçues et ne sont pas affichées.</p>${link(homeRecent.documentation,'ECMWF / Copernicus via Open-Meteo · CC BY 4.0')}`;
 }catch(e){if($('#home-recent'))$('#home-recent').innerHTML='<h3>Années récentes indisponibles</h3><p>'+esc(e.message)+'</p>';}
}
function homeBuilding(){modal('Avant de choisir un logement',`<p>Ces points ne changent pas le classement communal : ils servent à préparer une visite et un rendez-vous. Aucune estimation chiffrée du confort intérieur n’est calculée.</p><div class="home-checklist">${['Étage et situation sous toiture','Orientation des fenêtres et protections solaires extérieures','Possibilité de ventilation nocturne et de traversée de l’air','Isolation, DPE et travaux documentés','Risques connus à l’adresse, sinistres déclarés et diagnostics','Parcelle, zonage, prescriptions et documents applicables','Accès réel aux transports et services recherchés'].map(t=>`<label><input type="checkbox">${t}</label>`).join('')}</div><p>Les réponses restent dans cette fenêtre et ne sont pas enregistrées. Les vérifications ne constituent ni un diagnostic technique ni une autorisation administrative.</p><button id="home-check-export" class="outline">Exporter ma fiche de vérification</button>`);$('#home-check-export').onclick=()=>download('ChronoTerre_verifications.json',{commune:state.place.code,date:new Date().toISOString(),items:$$('.home-checklist label').map(l=>({question:l.textContent,checked:l.querySelector('input').checked})),limits:'Liste préparatoire personnelle. Aucun diagnostic du bâtiment ni autorisation de construire.'});}
window.ChronoHome={onPlace:homeOnPlace,onMode:()=>{if(state.mode==='past'){home.open=false;$('#home-panel').hidden=true;$('#place-panel').hidden=false;}homeMap();},onHorizon:()=>{home.ready=false;if($('#home-results'))$('#home-results').innerHTML='';if($('#home-horizon'))$('#home-horizon').value=state.horizon;if(home.open)homeRun();else{home.layer=false;homeMap();}},onSelect:()=>{if(home.open){home.open=false;$('#home-panel').hidden=true;$('#place-panel').hidden=false;}},onMapReady:homeMap};
document.addEventListener('chrono:ready',()=>{cities.forEach(c=>homeCities.set(c.code,c));homeRestore();$('#home-launch').onclick=homeOpen;homeOnPlace();if(homeStartWithProject&&state.mode==='living')homeOpen();});
